public struct AddShoppingListItemIntent: AppIntent {
    public static let title: LocalizedStringResource = "Add to list"
    public static let description = IntentDescription("Add or restore one item on the person's shopping list. It adds to the quantity of a matching item still on the list (same ingredient and unit); a removed or cleared matching item comes back at the added quantity, not on top of its old one.")

    @Parameter(title: "Item", description: "What to buy, such as eggs or flour.", requestValueDialog: "What should I add to your shopping list?")
    public var name: String
    @Parameter(title: "Quantity", description: "How many or how much, as a number above 0. Leave it out when it doesn't matter.")
    public var quantity: Double?
    @Parameter(title: "Unit", description: "The unit for the quantity, such as grams, cups or cans. Leave it out for a plain count.")
    public var unit: String?

    public init() {}

    public init(_ input: AddShoppingListItemInput) {
        self.init()
        self.name = input.name
        self.quantity = input.quantity
        self.unit = input.unit
    }

    public var input: AddShoppingListItemInput {
        AddShoppingListItemInput(name: name, quantity: quantity, unit: unit)
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<AddShoppingListItemOutput, any Error>
        do { result = .success(try await AddShoppingListItemAction.run(input)) } catch { result = .failure(error) }
        if let dialog = AddShoppingListItemAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

